children.onClick:
{{ (async () => { try {
 const kind=selCompanyDonorContactKind.selectedOptionValue;
 if(kind==='address') {
   const street=inpCompanyAddressStreet.text?.trim(); const unit=inpCompanyAddressUnit.text?.trim() || null;
   const city=inpCompanyAddressCity.text?.trim(); const state=inpCompanyAddressState.text?.trim();
   const postal=inpCompanyAddressPostal.text?.trim(); const country=inpCompanyAddressCountry.text?.trim() || 'USA';
   const reason=inpCompanyDonorContactReason.text?.trim() || inpCompanyAddressReason.text?.trim();
   if(!street || !city || !state || !postal || !reason) {showAlert('Enter an address and reason.','warning');return;}
   const r=await qAddCompanyDonorAddress.run({street,unit,city,state,postal,country,reason});
   if(!r?.[0]?.address_id) throw new Error('Address was not added.');
   await Promise.all([qCompanyDonorAddresses.run(),qCompanyContacts.run()]);
 } else {
   const reason=inpCompanyDonorContactReason.text?.trim(); const value=(kind==='phone' ? inpCompanyDonorPhone.text : inpCompanyDonorEmail.text)?.trim();
   if(!reason || !value || !['email','phone'].includes(kind)) {showAlert('Enter a contact and reason.','warning');return;}
   if(!(kind === 'phone' ? inpCompanyDonorPhone.isValid : inpCompanyDonorEmail.isValid)) {showAlert('Enter a valid email address or phone number.','warning');return;} const r=await qAddCompanyDonorContact.run({kind,value,reason});
   if(!r?.[0]?.contact_id) throw new Error('Contact was not added.');
   await Promise.all([qCompanyDonorContacts.run(),qCompanyContacts.run(),qCompanyProfile.run()]);
 }
 showAlert('Contributor contact added.','success');
} catch(e) {showAlert('Contact change failed: '+(e?.message||e),'error');} })() }}

{{ (async () => { try {
 const kind=selCompanyDonorContactKind.selectedOptionValue;
 const id=selCompanyDonorContactToArchive.selectedOptionValue;
 const reason=inpCompanyDonorContactReason.text?.trim() || (kind==='address' ? inpCompanyAddressReason.text?.trim() : '');
 if(!id || !reason) {showAlert('Select a contact and enter a reason.','warning');return;}
 if(kind==='address') {
   const r=await qArchiveCompanyDonorAddress.run({id,reason});
   if(!r?.[0]?.archived) throw new Error('Address was not archived.');
   await Promise.all([qCompanyDonorAddresses.run(),qCompanyContacts.run()]);
 } else {
   const entry=(qCompanyDonorContacts.data||[]).find(c=>c.contact_id===id);
   if(!entry || entry.contact_kind!==kind) throw new Error('Select a matching contact.');
   const r=await qArchiveCompanyDonorContact.run({kind,id,reason});
   if(!r?.[0]?.archived) throw new Error('Contact was not archived.');
   await Promise.all([qCompanyDonorContacts.run(),qCompanyContacts.run(),qCompanyProfile.run()]);
 }
 showAlert('Contributor contact archived.','success');
} catch(e) {showAlert('Contact archive failed: '+(e?.message||e),'error');} })() }}

{{ (async()=>{try{
const kind=selCompanyDonorContactKind.selectedOptionValue;
const contact=selCompanyDonorContactToArchive.selectedOptionValue;
const target=selCompanyContactReassignTarget.selectedOptionValue;
const reason=inpCompanyDonorContactReason.text?.trim();
if(!['email','phone','address'].includes(kind)||!contact||!target||!reason){showAlert('Select a contact, destination company and reason.','warning');return;}
const rows=await qReassignCompanyContact.run();
if(rows?.[0]?.reassigned!==true)throw new Error('Reassignment was not confirmed.');
await Promise.all([qCompanyDonorContacts.run(),qCompanyDonorAddresses.run(),qCompanyContacts.run(),qCompanyReassignTargets.run()]);
resetWidget('selCompanyContactReassignTarget',true);
showAlert('Company contact reassigned.','success');
}catch(e){showAlert('Contact reassignment failed: '+(e?.message||e),'error');}})() }}

