children.listData:
{{ (() => {
const entered = String(inpAssignStorageLocation.text || '').trim().toLowerCase();
if (entered.length < 2) return [];
const historic = (qLocationNameSuggestions.data || []).map(x => x.storage_location_name);
const raw = apiAvailableStorageProducts.data?.data || [];
const products = Array.isArray(raw) ? raw : [];
const locations = products.flatMap(p => [p.storage_location, ...(Array.isArray(p.storage_locations) ? p.storage_locations : [])]);
return [...new Set([...historic, ...locations].map(x => String(x || '').trim()).filter(Boolean))]
.filter(name => name.toLowerCase().includes(entered))
.sort((a,b) => a.localeCompare(b)).slice(0, 30)
.map(name => ({id:name,name}));
})() }}

