children.text:
{{
(() => {
  const selectedMember = String(
    selMember.selectedOptionValue ||
    appsmith.store.member_id ||
    ""
  ).trim();

  const memberRow = (qMembersDirectory.data || [])
    .find(m => String(m.member_id) === selectedMember);

  const memberLabel = memberRow
    ? `${memberRow.first_name || ""} ${memberRow.last_name || ""}`.trim()
    : selectedMember || navigationLabels.text("selected member");

  const releaseType = "sacrament_release";
  const releaseLabel = "Sacrament Release";

  if (!selectedMember) {
    return navigationLabels.text("Select a member to check eligibility.");
  }

  if (qGateCheckAgreement.isLoading) {
    return "Checking eligibility...";
  }

  const gateRow = qGateCheckAgreement.data?.[0] || null;

  if (gateRow?.member_agreement_id) {
    const signedLabel =
      gateRow.template_name ||
      releaseLabel ||
      "required agreement";

    return `✅ Eligible — ${memberLabel} has signed: ${signedLabel}`;
  }

  return `❌ Not eligible — ${memberLabel} has not signed: ${releaseLabel}`;
})()
}}

children.isDisabled:
{{
  (() => {
    const selectedMember = selMember.selectedOptionValue || appsmith.URL.queryParams.member_id || appsmith.store.member_id;
    const hasAgreement = qGateCheckAgreement.data && qGateCheckAgreement.data.length > 0;
    const isReviewer = appsmith.store.facilitator_is_reviewer === true;
    const hasNotes = !!(inpNotes.text && inpNotes.text.trim());
    const hasFacilitator = !!selFacilitator.selectedOptionValue;

    if (!selectedMember) return true;
    if (!hasFacilitator) return true;
    if (hasAgreement) return false;
    if (!isReviewer) return true;
    if (!hasNotes) return true;

    return false;
  })()
}}

